-- DRAFT PostgreSQL schema, translated mechanically from the Azure SQL catalog
-- (see azure-sql-schema.md). NOT yet tested against the app. Confirm PostgreSQL
-- with Jacob before using. Review it before relying on it.
--
-- Mapping: nvarchar(n)->varchar(n), nvarchar(max)->text, bit->boolean,
-- datetime/datetime2->timestamptz, uniqueidentifier->uuid, varbinary->bytea,
-- decimal->numeric, identity->generated by default as identity,
-- getdate()->now(), newid()->gen_random_uuid(), filtered index->partial index.
-- Index names are prefixed with the table name (Postgres index names are
-- schema-wide, SQL Server's are per table).

BEGIN;

CREATE TABLE accounts (
  account_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  item_id integer NOT NULL,
  plaid_account_id varchar(100) NOT NULL,
  account_name varchar(255),
  official_name varchar(255),
  account_type varchar(50) NOT NULL,
  account_subtype varchar(100),
  current_balance numeric(18,2),
  available_balance numeric(18,2),
  credit_limit numeric(18,2),
  is_active boolean DEFAULT true,
  closed_at timestamptz,
  include_in_cash_on_hand boolean DEFAULT true,
  include_in_operating_metrics boolean DEFAULT true,
  last_updated_datetime timestamptz,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  mask varchar(10),
  PRIMARY KEY (account_id)
);

CREATE TABLE client_external_ids (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  client_uuid uuid NOT NULL,
  external_system varchar(50) NOT NULL,
  external_id varchar(255) NOT NULL,
  matched_by varchar(100),
  match_method varchar(50),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  PRIMARY KEY (id)
);

CREATE TABLE clients (
  client_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  first_name varchar(100) NOT NULL,
  last_name varchar(100) NOT NULL,
  business_name varchar(255),
  email varchar(255) NOT NULL,
  phone_number varchar(20),
  account_type varchar(50) NOT NULL,
  fiscal_year_start_date date NOT NULL,
  state varchar(2) NOT NULL,
  federal_effective_tax_rate numeric(5,4),
  state_effective_tax_rate numeric(5,4),
  self_employment_tax_rate numeric(5,4),
  blended_effective_tax_rate numeric(5,4),
  target_tax_savings_percent numeric(5,4),
  income_type varchar(50),
  sync_status varchar(50) DEFAULT 'active',
  last_synced timestamptz,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  plaid_user_id varchar(100),
  is_archived boolean NOT NULL DEFAULT false,
  client_uuid uuid NOT NULL DEFAULT gen_random_uuid(),
  PRIMARY KEY (client_id)
);

CREATE TABLE documents (
  doc_id uuid NOT NULL DEFAULT gen_random_uuid(),
  client_uuid uuid NOT NULL,
  tax_year integer NOT NULL,
  blob_path varchar(500) NOT NULL,
  filename varchar(255) NOT NULL,
  file_size bigint NOT NULL,
  sha256_hash varchar(64) NOT NULL,
  uploaded_by varchar(100) NOT NULL,
  uploaded_at timestamptz DEFAULT now(),
  PRIMARY KEY (doc_id)
);

CREATE TABLE encryption_keys (
  key_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  key_name varchar(100) NOT NULL,
  key_value bytea NOT NULL,
  created_at timestamptz DEFAULT now(),
  expires_at timestamptz,
  is_active boolean DEFAULT true,
  PRIMARY KEY (key_id)
);

CREATE TABLE holdings (
  holding_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  account_id integer NOT NULL,
  security_id integer NOT NULL,
  plaid_account_id varchar(100) NOT NULL,
  plaid_security_id varchar(100) NOT NULL,
  quantity numeric(19,6) NOT NULL,
  cost_basis numeric(19,4),
  institution_price numeric(19,6) NOT NULL,
  institution_price_as_of date,
  institution_price_datetime timestamptz,
  institution_value numeric(19,4) NOT NULL,
  iso_currency_code varchar(10),
  unofficial_currency_code varchar(20),
  vested_quantity numeric(19,6),
  vested_value numeric(19,4),
  is_archived boolean DEFAULT false,
  archived_at timestamptz,
  archive_reason varchar(100),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  PRIMARY KEY (holding_id)
);

CREATE TABLE investment_transactions (
  investment_transaction_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  account_id integer NOT NULL,
  security_id integer,
  plaid_investment_transaction_id varchar(100) NOT NULL,
  plaid_account_id varchar(100) NOT NULL,
  plaid_security_id varchar(100),
  cancel_transaction_id varchar(100),
  transaction_date date NOT NULL,
  name varchar(500),
  amount numeric(19,4) NOT NULL,
  quantity numeric(19,6) NOT NULL,
  price numeric(19,6) NOT NULL,
  fees numeric(19,4),
  transaction_type varchar(50) NOT NULL,
  transaction_subtype varchar(50),
  iso_currency_code varchar(10),
  unofficial_currency_code varchar(20),
  is_archived boolean DEFAULT false,
  archived_at timestamptz,
  archive_reason varchar(100),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  PRIMARY KEY (investment_transaction_id)
);

CREATE TABLE items (
  item_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  client_id integer NOT NULL,
  plaid_item_id varchar(100) NOT NULL,
  access_token bytea NOT NULL,
  access_token_key_id integer NOT NULL,
  institution_id varchar(50),
  institution_name varchar(200),
  status varchar(50) DEFAULT 'active',
  last_error_code varchar(100),
  last_error_message text,
  last_error_timestamp timestamptz,
  error_attempt_count integer DEFAULT 0,
  consent_expiration_time timestamptz,
  transactions_cursor text,
  transactions_cursor_last_updated timestamptz,
  historical_transactions_cursor text,
  transactions_last_successful_update timestamptz,
  investments_last_successful_update timestamptz,
  has_sync_updates boolean DEFAULT false,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  is_oauth boolean NOT NULL DEFAULT false,
  is_archived boolean NOT NULL DEFAULT false,
  liabilities_last_successful_update timestamptz,
  liabilities_error_code varchar(100),
  investments_error_code varchar(100),
  investment_transactions_last_synced_at timestamptz,
  PRIMARY KEY (item_id)
);

CREATE TABLE liabilities_credit (
  credit_liability_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  account_id integer NOT NULL,
  is_overdue boolean DEFAULT false,
  last_payment_amount numeric(19,4),
  last_payment_date date,
  last_statement_balance numeric(19,4),
  last_statement_issue_date date,
  minimum_payment_amount numeric(19,4),
  next_payment_due_date date,
  is_archived boolean DEFAULT false,
  archived_at timestamptz,
  archive_reason varchar(100),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  PRIMARY KEY (credit_liability_id)
);

CREATE TABLE liabilities_credit_aprs (
  apr_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  credit_liability_id integer NOT NULL,
  apr_percentage numeric(7,4),
  apr_type varchar(50),
  balance_subject_to_apr numeric(19,4),
  interest_charge_amount numeric(19,4),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  PRIMARY KEY (apr_id)
);

CREATE TABLE liabilities_mortgage (
  mortgage_liability_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  account_id integer NOT NULL,
  account_number varchar(100),
  loan_type_description varchar(100),
  loan_term varchar(50),
  origination_date date,
  origination_principal_amount numeric(19,4),
  maturity_date date,
  interest_rate_percentage numeric(7,4),
  interest_rate_type varchar(20),
  property_address_city varchar(100),
  property_address_country varchar(50),
  property_address_postal_code varchar(20),
  property_address_region varchar(50),
  property_address_street varchar(255),
  has_pmi boolean,
  has_prepayment_penalty boolean,
  escrow_balance numeric(19,4),
  last_statement_balance numeric(19,4),
  current_late_fee numeric(19,4),
  past_due_amount numeric(19,4),
  last_payment_amount numeric(19,4),
  last_payment_date date,
  next_monthly_payment numeric(19,4),
  next_payment_due_date date,
  ytd_interest_paid numeric(19,4),
  ytd_principal_paid numeric(19,4),
  is_archived boolean DEFAULT false,
  archived_at timestamptz,
  archive_reason varchar(100),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  PRIMARY KEY (mortgage_liability_id)
);

CREATE TABLE liabilities_student (
  student_liability_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  account_id integer NOT NULL,
  account_number varchar(100),
  loan_name varchar(255),
  origination_date date,
  origination_principal_amount numeric(19,4),
  expected_payoff_date date,
  guarantor varchar(255),
  interest_rate_percentage numeric(7,4),
  loan_status_type varchar(50),
  loan_status_end_date date,
  repayment_plan_type varchar(100),
  repayment_plan_description varchar(255),
  last_statement_balance numeric(19,4),
  last_statement_issue_date date,
  outstanding_interest_amount numeric(19,4),
  is_overdue boolean DEFAULT false,
  last_payment_amount numeric(19,4),
  last_payment_date date,
  minimum_payment_amount numeric(19,4),
  next_payment_due_date date,
  ytd_interest_paid numeric(19,4),
  ytd_principal_paid numeric(19,4),
  servicer_address_city varchar(100),
  servicer_address_country varchar(50),
  servicer_address_postal_code varchar(20),
  servicer_address_region varchar(50),
  servicer_address_street varchar(255),
  disbursement_dates text,
  is_archived boolean DEFAULT false,
  archived_at timestamptz,
  archive_reason varchar(100),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  PRIMARY KEY (student_liability_id)
);

CREATE TABLE link_sessions (
  session_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  link_token varchar(255) NOT NULL,
  link_session_id varchar(100),
  status varchar(50) NOT NULL,
  error_code varchar(100),
  error_message varchar(500),
  error_type varchar(100),
  institution_id varchar(50),
  institution_name varchar(100),
  created_at timestamptz DEFAULT now(),
  PRIMARY KEY (session_id)
);

CREATE TABLE link_tokens (
  link_token varchar(255) NOT NULL,
  client_id integer NOT NULL,
  status varchar(50) DEFAULT 'pending',
  hosted_link_url varchar(500),
  expires_at timestamptz NOT NULL,
  created_at timestamptz DEFAULT now(),
  used_at timestamptz,
  last_session_status varchar(50),
  last_session_error_code varchar(100),
  last_session_error_message varchar(500),
  attempt_count integer DEFAULT 0,
  link_session_id varchar(100),
  PRIMARY KEY (link_token)
);

CREATE TABLE securities (
  security_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  plaid_security_id varchar(100) NOT NULL,
  isin varchar(20),
  cusip varchar(20),
  institution_security_id varchar(100),
  institution_id varchar(50),
  proxy_security_id varchar(100),
  name varchar(500),
  ticker_symbol varchar(50),
  market_identifier_code varchar(10),
  security_type varchar(50),
  security_subtype varchar(100),
  sector varchar(100),
  industry varchar(100),
  close_price numeric(19,6),
  close_price_as_of date,
  update_datetime timestamptz,
  iso_currency_code varchar(10),
  unofficial_currency_code varchar(20),
  is_cash_equivalent boolean DEFAULT false,
  option_contract text,
  fixed_income text,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  PRIMARY KEY (security_id)
);

CREATE TABLE transactions (
  transaction_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  account_id integer NOT NULL,
  plaid_transaction_id varchar(100) NOT NULL,
  transaction_date date NOT NULL,
  transaction_datetime timestamptz,
  posted_date date,
  authorized_date date,
  merchant_name varchar(255),
  original_description varchar(500),
  merchant_logo_url varchar(500),
  merchant_website varchar(500),
  amount numeric(18,2) NOT NULL,
  iso_currency_code varchar(10) DEFAULT 'USD',
  payment_channel varchar(50),
  transaction_code varchar(50),
  pending boolean DEFAULT false,
  is_transfer boolean DEFAULT false,
  transaction_status varchar(50) DEFAULT 'added',
  is_removed boolean DEFAULT false,
  plaid_primary_category varchar(100),
  plaid_detailed_category varchar(100),
  plaid_confidence_score numeric(5,4),
  category_verified boolean DEFAULT false,
  final_category varchar(100) DEFAULT 'not_verified',
  processed_into_ledger boolean DEFAULT false,
  updated_since_process boolean DEFAULT false,
  sync_status varchar(50) DEFAULT 'not_ready',
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  is_archived boolean NOT NULL DEFAULT false,
  archived_at timestamptz,
  archive_reason varchar(50),
  manually_verified boolean DEFAULT false,
  manual_primary_category varchar(100),
  manual_detailed_category varchar(100),
  PRIMARY KEY (transaction_id)
);

CREATE TABLE webhook_log (
  log_id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  webhook_type varchar(100) NOT NULL,
  webhook_code varchar(100) NOT NULL,
  item_id integer,
  plaid_item_id varchar(100),
  payload text NOT NULL,
  processed boolean DEFAULT false,
  processed_at timestamptz,
  error_message text,
  webhook_id varchar(255) NOT NULL,
  created_at timestamptz DEFAULT now(),
  PRIMARY KEY (log_id)
);

CREATE INDEX ix_accounts_account_subtype ON accounts (account_subtype);
CREATE INDEX ix_accounts_account_type ON accounts (account_type);
CREATE INDEX ix_accounts_is_active ON accounts (is_active);
CREATE INDEX ix_accounts_is_active_dup ON accounts (is_active);
CREATE INDEX ix_accounts_item_id ON accounts (item_id);
CREATE INDEX ix_accounts_plaid_account_id ON accounts (plaid_account_id);
CREATE INDEX ix_accounts_item_type_mask ON accounts (item_id, account_type, account_subtype, mask);
CREATE UNIQUE INDEX uq_accounts_plaid_account_id ON accounts (plaid_account_id);
CREATE INDEX ix_client_external_ids_external_system_id ON client_external_ids (external_system, external_id);
CREATE UNIQUE INDEX ix_client_external_ids_uq_client_external ON client_external_ids (client_uuid, external_system);
CREATE INDEX ix_clients_account_type ON clients (account_type);
CREATE INDEX ix_clients_client_uuid ON clients (client_uuid);
CREATE INDEX ix_clients_is_archived ON clients (is_archived);
CREATE INDEX ix_clients_email ON clients (email);
CREATE INDEX ix_clients_state ON clients (state);
CREATE INDEX ix_clients_sync_status ON clients (sync_status);
CREATE UNIQUE INDEX ix_clients_plaid_user_id ON clients (plaid_user_id) WHERE plaid_user_id IS NOT NULL;
CREATE UNIQUE INDEX uq_clients_email ON clients (email);
CREATE UNIQUE INDEX ix_clients_uq_clients_client_uuid ON clients (client_uuid);
CREATE INDEX ix_documents_client_uuid ON documents (client_uuid);
CREATE INDEX ix_documents_sha256 ON documents (sha256_hash);
CREATE INDEX ix_documents_tax_year ON documents (tax_year);
CREATE INDEX ix_encryption_keys_is_active ON encryption_keys (is_active);
CREATE INDEX ix_encryption_keys_key_name ON encryption_keys (key_name);
CREATE UNIQUE INDEX uq_encryption_keys_key_name ON encryption_keys (key_name);
CREATE INDEX ix_holdings_account_active ON holdings (account_id, is_archived) WHERE is_archived = false;
CREATE INDEX ix_holdings_account_id ON holdings (account_id);
CREATE INDEX ix_holdings_is_archived ON holdings (is_archived);
CREATE INDEX ix_holdings_plaid_account_id ON holdings (plaid_account_id);
CREATE INDEX ix_holdings_security_id ON holdings (security_id);
CREATE INDEX ix_investment_transactions_account_date ON investment_transactions (account_id, transaction_date) WHERE is_archived = false;
CREATE INDEX ix_investment_transactions_account_id ON investment_transactions (account_id);
CREATE INDEX ix_investment_transactions_date ON investment_transactions (transaction_date);
CREATE INDEX ix_investment_transactions_is_archived ON investment_transactions (is_archived);
CREATE INDEX ix_investment_transactions_plaid_account ON investment_transactions (plaid_account_id);
CREATE INDEX ix_investment_transactions_security_id ON investment_transactions (security_id);
CREATE INDEX ix_investment_transactions_type ON investment_transactions (transaction_type);
CREATE UNIQUE INDEX ix_investment_transactions_uq_investment_transactions_plaid_id ON investment_transactions (plaid_investment_transaction_id);
CREATE INDEX ix_items_client_id ON items (client_id);
CREATE INDEX ix_items_consent_expiration ON items (consent_expiration_time);
CREATE INDEX ix_items_has_sync_updates ON items (has_sync_updates);
CREATE INDEX ix_items_is_archived ON items (is_archived);
CREATE INDEX ix_items_last_error_code ON items (last_error_code);
CREATE INDEX ix_items_plaid_item_id ON items (plaid_item_id);
CREATE INDEX ix_items_status ON items (status);
CREATE INDEX ix_items_is_oauth ON items (is_oauth) WHERE is_oauth = true;
CREATE UNIQUE INDEX uq_items_plaid_item_id ON items (plaid_item_id);
CREATE INDEX ix_liabilities_credit_account ON liabilities_credit (account_id);
CREATE INDEX ix_liabilities_credit_archived ON liabilities_credit (is_archived);
CREATE INDEX ix_liabilities_credit_overdue ON liabilities_credit (is_overdue) WHERE is_overdue = true;
CREATE INDEX ix_liabilities_credit_aprs_credit_aprs_liability ON liabilities_credit_aprs (credit_liability_id);
CREATE INDEX ix_liabilities_mortgage_account ON liabilities_mortgage (account_id);
CREATE INDEX ix_liabilities_mortgage_archived ON liabilities_mortgage (is_archived);
CREATE INDEX ix_liabilities_mortgage_pastdue ON liabilities_mortgage (past_due_amount) WHERE past_due_amount > 0;
CREATE INDEX ix_liabilities_student_account ON liabilities_student (account_id);
CREATE INDEX ix_liabilities_student_archived ON liabilities_student (is_archived);
CREATE INDEX ix_liabilities_student_overdue ON liabilities_student (is_overdue) WHERE is_overdue = true;
CREATE INDEX ix_link_sessions_link_token ON link_sessions (link_token);
CREATE INDEX ix_link_sessions_status ON link_sessions (status);
CREATE INDEX ix_link_tokens_client_id ON link_tokens (client_id);
CREATE INDEX ix_link_tokens_expires_at ON link_tokens (expires_at);
CREATE INDEX ix_link_tokens_status ON link_tokens (status);
CREATE INDEX ix_securities_cusip ON securities (cusip) WHERE cusip IS NOT NULL;
CREATE INDEX ix_securities_isin ON securities (isin) WHERE isin IS NOT NULL;
CREATE INDEX ix_securities_security_type ON securities (security_type);
CREATE INDEX ix_securities_ticker_symbol ON securities (ticker_symbol);
CREATE UNIQUE INDEX ix_securities_uq_securities_plaid_security_id ON securities (plaid_security_id);
CREATE INDEX ix_transactions_account_id ON transactions (account_id);
CREATE INDEX ix_transactions_category_verified ON transactions (category_verified);
CREATE INDEX ix_transactions_is_transfer ON transactions (is_transfer);
CREATE INDEX ix_transactions_merchant_name ON transactions (merchant_name);
CREATE INDEX ix_transactions_pending ON transactions (pending);
CREATE INDEX ix_transactions_plaid_confidence_score ON transactions (plaid_confidence_score);
CREATE INDEX ix_transactions_plaid_transaction_id ON transactions (plaid_transaction_id);
CREATE INDEX ix_transactions_posted_date ON transactions (posted_date);
CREATE INDEX ix_transactions_processed_into_ledger ON transactions (processed_into_ledger);
CREATE INDEX ix_transactions_sync_status ON transactions (sync_status);
CREATE INDEX ix_transactions_transaction_date ON transactions (transaction_date);
CREATE INDEX ix_transactions_is_archived ON transactions (is_archived);
CREATE UNIQUE INDEX uq_transactions_plaid_transaction_id ON transactions (plaid_transaction_id);
CREATE INDEX ix_webhook_log_created_at ON webhook_log (created_at);
CREATE INDEX ix_webhook_log_item_id ON webhook_log (item_id);
CREATE INDEX ix_webhook_log_processed ON webhook_log (processed);
CREATE INDEX ix_webhook_log_webhook_code ON webhook_log (webhook_code);
CREATE INDEX ix_webhook_log_webhook_id ON webhook_log (webhook_id);
CREATE INDEX ix_webhook_log_webhook_type ON webhook_log (webhook_type);
CREATE UNIQUE INDEX uq_webhook_log_webhook_id ON webhook_log (webhook_id);

ALTER TABLE accounts ADD CONSTRAINT fk_accounts_item_id FOREIGN KEY (item_id) REFERENCES items (item_id);
ALTER TABLE client_external_ids ADD CONSTRAINT fk_client_external_ids_client_uuid FOREIGN KEY (client_uuid) REFERENCES clients (client_uuid);
ALTER TABLE documents ADD CONSTRAINT fk_documents_client_uuid FOREIGN KEY (client_uuid) REFERENCES clients (client_uuid);
ALTER TABLE holdings ADD CONSTRAINT fk_holdings_account_id FOREIGN KEY (account_id) REFERENCES accounts (account_id);
ALTER TABLE holdings ADD CONSTRAINT fk_holdings_security_id FOREIGN KEY (security_id) REFERENCES securities (security_id);
ALTER TABLE investment_transactions ADD CONSTRAINT fk_investment_transactions_account_id FOREIGN KEY (account_id) REFERENCES accounts (account_id);
ALTER TABLE investment_transactions ADD CONSTRAINT fk_investment_transactions_security_id FOREIGN KEY (security_id) REFERENCES securities (security_id);
ALTER TABLE items ADD CONSTRAINT fk_items_access_token_key_id FOREIGN KEY (access_token_key_id) REFERENCES encryption_keys (key_id);
ALTER TABLE items ADD CONSTRAINT fk_items_client_id FOREIGN KEY (client_id) REFERENCES clients (client_id);
ALTER TABLE liabilities_credit ADD CONSTRAINT fk_liabilities_credit_account_id FOREIGN KEY (account_id) REFERENCES accounts (account_id);
ALTER TABLE liabilities_credit_aprs ADD CONSTRAINT fk_liabilities_credit_aprs_credit_liability_id FOREIGN KEY (credit_liability_id) REFERENCES liabilities_credit (credit_liability_id) ON DELETE CASCADE;
ALTER TABLE liabilities_mortgage ADD CONSTRAINT fk_liabilities_mortgage_account_id FOREIGN KEY (account_id) REFERENCES accounts (account_id);
ALTER TABLE liabilities_student ADD CONSTRAINT fk_liabilities_student_account_id FOREIGN KEY (account_id) REFERENCES accounts (account_id);
ALTER TABLE link_sessions ADD CONSTRAINT fk_link_sessions_link_token FOREIGN KEY (link_token) REFERENCES link_tokens (link_token);
ALTER TABLE link_tokens ADD CONSTRAINT fk_link_tokens_client_id FOREIGN KEY (client_id) REFERENCES clients (client_id);
ALTER TABLE transactions ADD CONSTRAINT fk_transactions_account_id FOREIGN KEY (account_id) REFERENCES accounts (account_id);
ALTER TABLE webhook_log ADD CONSTRAINT fk_webhook_log_item_id FOREIGN KEY (item_id) REFERENCES items (item_id);

-- Views (translated from T-SQL; vw_failed_link_attempts changed: + to ||,
-- ISNULL to COALESCE, GETDATE() to now(), DATEADD to an interval).
CREATE VIEW vw_holdings_with_securities AS
SELECT 
    h.holding_id,
    h.account_id,
    h.security_id,
    h.plaid_account_id,
    h.plaid_security_id,
    h.quantity,
    h.cost_basis,
    h.institution_price,
    h.institution_price_as_of,
    h.institution_price_datetime,
    h.institution_value,
    h.iso_currency_code,
    h.unofficial_currency_code,
    h.vested_quantity,
    h.vested_value,
    h.is_archived,
    h.created_at,
    h.updated_at,
    s.name AS security_name,
    s.ticker_symbol,
    s.security_type,
    s.security_subtype,
    s.sector,
    s.industry,
    s.close_price,
    s.close_price_as_of,
    s.is_cash_equivalent,
    s.market_identifier_code,
    s.option_contract,
    s.fixed_income,
    a.account_name,
    a.account_type,
    a.account_subtype,
    a.item_id
FROM holdings h
JOIN securities s ON h.security_id = s.security_id
JOIN accounts a ON h.account_id = a.account_id;

CREATE VIEW vw_investment_transactions_with_securities AS
SELECT 
    it.investment_transaction_id,
    it.account_id,
    it.security_id,
    it.plaid_investment_transaction_id,
    it.plaid_account_id,
    it.plaid_security_id,
    it.cancel_transaction_id,
    it.transaction_date,
    it.name,
    it.amount,
    it.quantity,
    it.price,
    it.fees,
    it.transaction_type,
    it.transaction_subtype,
    it.iso_currency_code,
    it.unofficial_currency_code,
    it.is_archived,
    it.created_at,
    it.updated_at,
    s.name AS security_name,
    s.ticker_symbol,
    s.security_type,
    s.security_subtype,
    s.sector,
    s.industry,
    a.account_name,
    a.account_type,
    a.account_subtype,
    a.item_id
FROM investment_transactions it
LEFT JOIN securities s ON it.security_id = s.security_id
JOIN accounts a ON it.account_id = a.account_id;

CREATE VIEW vw_failed_link_attempts AS
SELECT 
    lt.link_token,
    lt.client_id,
    c.first_name || ' ' || c.last_name AS client_name,
    c.email AS client_email,
    lt.status AS link_status,
    lt.last_session_status,
    lt.last_session_error_code,
    lt.last_session_error_message,
    COALESCE(lt.attempt_count, 0) AS attempt_count,
    lt.created_at AS link_created_at,
    lt.expires_at AS link_expires_at,
    lt.used_at AS last_attempt_at,
    CASE 
        WHEN lt.status = 'used' THEN 'completed'
        WHEN lt.expires_at < now() THEN 'expired'
        WHEN lt.last_session_status IN ('EXITED', 'REQUIRES_CREDENTIALS', 'REQUIRES_QUESTIONS', 'REQUIRES_SELECTIONS') THEN 'needs_retry'
        WHEN lt.last_session_status IS NULL THEN 'pending'
        ELSE 'unknown'
    END AS action_needed
FROM link_tokens lt
JOIN clients c ON lt.client_id = c.client_id
WHERE lt.status != 'used'
  AND lt.expires_at > now() - interval '7 days';

COMMIT;
